131	  public void init(int heartbeatInterval,
132	      List<ContainerSimulator> containerList, ResourceManager resourceManager,
133	      SLSRunner slsRunnner, long startTime, long finishTime, String simUser,
134	      String simQueue, boolean tracked, String oldApp, long baseTimeMS,
135	      Resource amResource, String nodeLabelExpr, Map<String, String> params,
136	      Map<ApplicationId, AMSimulator> appIdAMSim) {
137	    super.init(startTime, startTime + 1000000L * heartbeatInterval,
138	        heartbeatInterval);
139	    this.user = simUser;
140	    this.rm = resourceManager;
141	    this.se = slsRunnner;
142	    this.queue = simQueue;
143	    this.oldAppId = oldApp;
144	    this.isTracked = tracked;
145	    this.baselineTimeMS = baseTimeMS;
146	    this.traceStartTimeMS = startTime;
147	    this.traceFinishTimeMS = finishTime;
148	    this.amContainerResource = amResource;
149	    this.nodeLabelExpression = nodeLabelExpr;
150	    this.appIdToAMSim = appIdAMSim;
151	  }
