153	  /**
154	   * register with RM
155	   */
156	  @Override
157	  public void firstStep() throws Exception {
158	    simulateStartTimeMS = System.currentTimeMillis() - baselineTimeMS;
159	
160	    ReservationId reservationId = null;
161	
162	    // submit a reservation if one is required, exceptions naturally happen
163	    // when the reservation does not fit, catch, log, and move on running job
164	    // without reservation.
165	    try {
166	      reservationId = submitReservationWhenSpecified();
167	    } catch (UndeclaredThrowableException y) {
168	      LOG.warn("Unable to place reservation: " + y.getMessage());
169	    }
170	
171	    // submit application, waiting until ACCEPTED
172	    submitApp(reservationId);
173	
174	    // add submitted app to mapping
175	    appIdToAMSim.put(appId, this);
176	
177	    // track app metrics
178	    trackApp();
179	  }
