181	  public synchronized void notifyAMContainerLaunched(Container masterContainer)
182	      throws Exception {
183	    this.amContainer = masterContainer;
184	    this.appAttemptId = masterContainer.getId().getApplicationAttemptId();
185	    registerAM();
186	    isAMContainerRunning = true;
187	  }
