193	  private ReservationId submitReservationWhenSpecified()
194	      throws IOException, InterruptedException {
195	    if (reservationRequest != null) {
196	      UserGroupInformation ugi = UserGroupInformation.createRemoteUser(user);
197	      ugi.doAs(new PrivilegedExceptionAction<Object>() {
198	        @Override
199	        public Object run() throws YarnException, IOException {
200	          rm.getClientRMService().submitReservation(reservationRequest);
201	          LOG.info("RESERVATION SUCCESSFULLY SUBMITTED "
202	              + reservationRequest.getReservationId());
203	          return null;
204	
205	        }
206	      });
207	      return reservationRequest.getReservationId();
208	    } else {
209	      return null;
210	    }
211	  }
