213	  @Override
214	  public void middleStep() throws Exception {
215	    if (isAMContainerRunning) {
216	      // process responses in the queue
217	      processResponseQueue();
218	
219	      // send out request
220	      sendContainerRequest();
221	
222	      // check whether finish
223	      checkStop();
224	    }
225	  }
