227	  @Override
228	  public void lastStep() throws Exception {
229	    LOG.info("Application {} is shutting down.", appId);
230	    // unregister tracking
231	    if (isTracked) {
232	      untrackApp();
233	    }
234	
235	    // Finish AM container
236	    if (amContainer != null) {
237	      LOG.info("AM container = {} reported to finish", amContainer.getId());
238	      se.getNmMap().get(amContainer.getNodeId()).cleanupContainer(
239	          amContainer.getId());
240	    } else {
241	      LOG.info("AM container is null");
242	    }
243	
244	    // Clear runningApps for ranNodes of this app
245	    for (NodeId nodeId : ranNodes) {
246	      se.getNmMap().get(nodeId).finishApplication(getApplicationId());
247	    }
248	
249	    if (null == appAttemptId) {
250	      // If appAttemptId == null, AM is not launched from RM's perspective, so
251	      // it's unnecessary to finish am as well
252	      return;
253	    }
254	
255	    // unregister application master
256	    final FinishApplicationMasterRequest finishAMRequest = recordFactory
257	                  .newRecordInstance(FinishApplicationMasterRequest.class);
258	    finishAMRequest.setFinalApplicationStatus(FinalApplicationStatus.SUCCEEDED);
259	
260	    UserGroupInformation ugi =
261	        UserGroupInformation.createRemoteUser(appAttemptId.toString());
262	    Token<AMRMTokenIdentifier> token = rm.getRMContext().getRMApps().get(appId)
263	        .getRMAppAttempt(appAttemptId).getAMRMToken();
264	    ugi.addTokenIdentifier(token.decodeIdentifier());
265	    ugi.doAs(new PrivilegedExceptionAction<Object>() {
266	      @Override
267	      public Object run() throws Exception {
268	        rm.getApplicationMasterService()
269	            .finishApplicationMaster(finishAMRequest);
270	        return null;
271	      }
272	    });
273	
274	    simulateFinishTimeMS = System.currentTimeMillis() - baselineTimeMS;
275	    // record job running information
276	    SchedulerMetrics schedulerMetrics =
277	            ((SchedulerWrapper)rm.getResourceScheduler()).getSchedulerMetrics();
278	    if (schedulerMetrics != null) {
279	      schedulerMetrics.addAMRuntime(appId, traceStartTimeMS, traceFinishTimeMS,
280	              simulateStartTimeMS, simulateFinishTimeMS);
281	    }
282	  }
