284	  protected ResourceRequest createResourceRequest(Resource resource,
285	      ExecutionType executionType, String host, int priority, long
286	      allocationId, int numContainers) {
287	    ResourceRequest request = recordFactory
288	        .newRecordInstance(ResourceRequest.class);
289	    request.setCapability(resource);
290	    request.setResourceName(host);
291	    request.setNumContainers(numContainers);
292	    request.setExecutionTypeRequest(
293	        ExecutionTypeRequest.newInstance(executionType));
294	    Priority prio = recordFactory.newRecordInstance(Priority.class);
295	    prio.setPriority(priority);
296	    request.setPriority(prio);
297	    request.setAllocationRequestId(allocationId);
298	    return request;
299	  }
