324	  private void submitApp(ReservationId reservationId)
325	          throws YarnException, InterruptedException, IOException {
326	    // ask for new application
327	    GetNewApplicationRequest newAppRequest =
328	        Records.newRecord(GetNewApplicationRequest.class);
329	    GetNewApplicationResponse newAppResponse =
330	        rm.getClientRMService().getNewApplication(newAppRequest);
331	    appId = newAppResponse.getApplicationId();
332	
333	    // submit the application
334	    final SubmitApplicationRequest subAppRequest =
335	        Records.newRecord(SubmitApplicationRequest.class);
336	    ApplicationSubmissionContext appSubContext =
337	        Records.newRecord(ApplicationSubmissionContext.class);
338	    appSubContext.setApplicationId(appId);
339	    appSubContext.setMaxAppAttempts(1);
340	    appSubContext.setQueue(queue);
341	    appSubContext.setPriority(Priority.newInstance(0));
342	    ContainerLaunchContext conLauContext =
343	        Records.newRecord(ContainerLaunchContext.class);
344	    conLauContext.setApplicationACLs(new HashMap<>());
345	    conLauContext.setCommands(new ArrayList<>());
346	    conLauContext.setEnvironment(new HashMap<>());
347	    conLauContext.setLocalResources(new HashMap<>());
348	    conLauContext.setServiceData(new HashMap<>());
349	    appSubContext.setAMContainerSpec(conLauContext);
350	    appSubContext.setResource(amContainerResource);
351	    if (nodeLabelExpression != null) {
352	      appSubContext.setNodeLabelExpression(nodeLabelExpression);
353	    }
354	
355	    if(reservationId != null) {
356	      appSubContext.setReservationID(reservationId);
357	    }
358	
359	    subAppRequest.setApplicationSubmissionContext(appSubContext);
360	    UserGroupInformation ugi = UserGroupInformation.createRemoteUser(user);
361	    ugi.doAs(new PrivilegedExceptionAction<Object>() {
362	      @Override
363	      public Object run() throws YarnException, IOException {
364	        rm.getClientRMService().submitApplication(subAppRequest);
365	        return null;
366	      }
367	    });
368	    LOG.info("Submit a new application {}", appId);
369	  }
