371	  private void registerAM()
372	          throws YarnException, IOException, InterruptedException {
373	    // register application master
374	    final RegisterApplicationMasterRequest amRegisterRequest =
375	            Records.newRecord(RegisterApplicationMasterRequest.class);
376	    amRegisterRequest.setHost("localhost");
377	    amRegisterRequest.setRpcPort(1000);
378	    amRegisterRequest.setTrackingUrl("localhost:1000");
379	
380	    UserGroupInformation ugi =
381	        UserGroupInformation.createRemoteUser(appAttemptId.toString());
382	    Token<AMRMTokenIdentifier> token = rm.getRMContext().getRMApps().get(appId)
383	        .getRMAppAttempt(appAttemptId).getAMRMToken();
384	    ugi.addTokenIdentifier(token.decodeIdentifier());
385	
386	    ugi.doAs(
387	            new PrivilegedExceptionAction<RegisterApplicationMasterResponse>() {
388	      @Override
389	      public RegisterApplicationMasterResponse run() throws Exception {
390	        return rm.getApplicationMasterService()
391	                .registerApplicationMaster(amRegisterRequest);
392	      }
393	    });
394	
395	    LOG.info("Register the application master for application {}", appId);
396	  }
