398	  private void trackApp() {
399	    if (isTracked) {
400	      SchedulerMetrics schedulerMetrics =
401	          ((SchedulerWrapper)rm.getResourceScheduler()).getSchedulerMetrics();
402	      if (schedulerMetrics != null) {
403	        schedulerMetrics.addTrackedApp(appId, oldAppId);
404	      }
405	    }
406	  }
407	  public void untrackApp() {
408	    if (isTracked) {
409	      SchedulerMetrics schedulerMetrics =
410	          ((SchedulerWrapper)rm.getResourceScheduler()).getSchedulerMetrics();
411	      if (schedulerMetrics != null) {
412	        schedulerMetrics.removeTrackedApp(oldAppId);
413	      }
414	    }
415	  }
