417	  protected List<ResourceRequest> packageRequests(
418	          List<ContainerSimulator> csList, int priority) {
419	    // create requests
420	    Map<Long, Map<String, ResourceRequest>> rackLocalRequests =
421	        new HashMap<>();
422	    Map<Long, Map<String, ResourceRequest>> nodeLocalRequests =
423	        new HashMap<>();
424	    Map<Long, ResourceRequest> anyRequests = new HashMap<>();
425	    for (ContainerSimulator cs : csList) {
426	      long allocationId = cs.getAllocationId();
427	      ResourceRequest anyRequest = anyRequests.get(allocationId);
428	      if (cs.getHostname() != null) {
429	        Map<String, ResourceRequest> rackLocalRequestMap;
430	        if (rackLocalRequests.containsKey(allocationId)) {
431	          rackLocalRequestMap = rackLocalRequests.get(allocationId);
432	        } else {
433	          rackLocalRequestMap = new HashMap<>();
434	          rackLocalRequests.put(allocationId, rackLocalRequestMap);
435	        }
436	        String[] rackHostNames = SLSUtils.getRackHostName(cs.getHostname());
437	        // check rack local
438	        String rackname = "/" + rackHostNames[0];
439	        if (rackLocalRequestMap.containsKey(rackname)) {
440	          rackLocalRequestMap.get(rackname).setNumContainers(
441	              rackLocalRequestMap.get(rackname).getNumContainers() + 1);
442	        } else {
443	          ResourceRequest request = createResourceRequest(cs.getResource(),
444	              cs.getExecutionType(), rackname, priority,
445	              cs.getAllocationId(), 1);
446	          rackLocalRequestMap.put(rackname, request);
447	        }
448	        // check node local
449	        Map<String, ResourceRequest> nodeLocalRequestMap;
450	        if (nodeLocalRequests.containsKey(allocationId)) {
451	          nodeLocalRequestMap = nodeLocalRequests.get(allocationId);
452	        } else {
453	          nodeLocalRequestMap = new HashMap<>();
454	          nodeLocalRequests.put(allocationId, nodeLocalRequestMap);
455	        }
456	        String hostname = rackHostNames[1];
457	        if (nodeLocalRequestMap.containsKey(hostname)) {
458	          nodeLocalRequestMap.get(hostname).setNumContainers(
459	              nodeLocalRequestMap.get(hostname).getNumContainers() + 1);
460	        } else {
461	          ResourceRequest request = createResourceRequest(cs.getResource(),
462	              cs.getExecutionType(), hostname, priority,
463	              cs.getAllocationId(), 1);
464	          nodeLocalRequestMap.put(hostname, request);
465	        }
466	      }
467	      // any
468	      if (anyRequest == null) {
469	        anyRequest = createResourceRequest(cs.getResource(),
470	            cs.getExecutionType(), ResourceRequest.ANY, priority,
471	            cs.getAllocationId(), 1);
472	        anyRequests.put(allocationId, anyRequest);
473	      } else {
474	        anyRequest.setNumContainers(anyRequest.getNumContainers() + 1);
475	      }
476	    }
477	    List<ResourceRequest> ask = new ArrayList<ResourceRequest>();
478	    for (Map<String, ResourceRequest> nodeLocalRequestMap :
479	        nodeLocalRequests.values()) {
480	      ask.addAll(nodeLocalRequestMap.values());
481	    }
482	    for (Map<String, ResourceRequest> rackLocalRequestMap :
483	        rackLocalRequests.values()) {
484	      ask.addAll(rackLocalRequestMap.values());
485	    }
486	    ask.addAll(anyRequests.values());
487	    return ask;
488	  }
